create policy "Authorised staff can update case updates" on public.case_updates for update to authenticated using ((admin_id = (select auth.uid()) or public.is_super_admin((select auth.uid()))) and (public.is_super_admin((select auth.uid())) or exists (select 1 from public.incidents i where i.id = incident_id and i.campus = public.get_user_campus((select auth.uid()))))) with check ((admin_id = (select auth.uid()) or public.is_super_admin((select auth.uid()))) and (public.is_super_admin((select auth.uid())) or exists (select 1 from public.incidents i where i.id = incident_id and i.campus = public.get_user_campus((select auth.uid())))));